//code forked from reddit user victx https://www.reddit.com/r/p5js/comments/1h4yygb/animated_grid_warping/
function setup() 
{
  createCanvas(1400, 600);
  stroke("#1d1d1b");
}

function draw() 
{
  background("#f9f0de");
	let border=4
	let resolution=4
  randomSeed(1);
  let xT = random(), yT = random();
  let xInc = 1/random(25000);
  let yInc = 1/random(50);
  for(let i = border; i < width - border; i+=resolution)
	{
    yT = 0;
    for(let j = border; j < height - border; j+=resolution)
		{
      strokeWeight(map(noise(xT,yT, frameCount/150),0,1,1,6))
      let angle = map(noise(xT,yT, frameCount/150),0,1,-TAU,TAU);
      point(i,j);
      xT+=xInc;
      yT+=yInc;
    }   
  }
}

